// @name Video from URL
// One video from a web address, played on the whole screen: a file
// (https://…/clip.mp4, .webm, .mkv), a live stream (an HLS .m3u8 playlist)
// or a camera (rtsp://). Looped by default, and a stream that drops is opened
// again. A tap pauses and plays. Plays on a Raspberry Pi (docs/video.md).
let paused = false

const clock = (s) => (s >= 0 ? `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}` : '')

export function get(app, context) {
  const width = context?.imageWidth ?? app.frame.width
  const height = context?.imageHeight ?? app.frame.height
  const k = Math.max(0.6, Math.min(1.6, Math.min(width / 800, height / 480) * 1.15))
  const url = String(app.state.url ?? '').trim()
  if (!url) {
    // Read on any panel: 14 px at the least, in a column 70 % of the width
    // and centred (inside the circle on a round one), white on e-paper.
    return (
      <div className="w-full h-full flex flex-col items-center justify-center gap-[8px] bg-black text-white">
        <span className={`text-[${Math.max(18, Math.round(22 * k))}px] font-bold`}>Video from URL</span>
        <span className={`w-[${Math.round(width * 0.7)}px] text-[${Math.max(14, Math.round(15 * k))}px] ${app.frame.paper ? 'text-white' : 'text-white/70'} text-center`}>
          Give the video's address in the scene's settings: an .mp4 or .webm file, an .m3u8 stream or an rtsp:// camera.
        </span>
      </div>
    )
  }
  const fit = app.state.fit === 'cover' ? 'cover' : app.state.fit === 'fill' ? 'fill' : 'contain'
  const video = frameos.video('url', {
    src: url,
    loop: app.state.loop !== false,
    paused,
    fit,
    fps: Number(app.state.fps) || 30,
  })
  return (
    <div className="relative w-full h-full bg-black" onClick={() => { paused = !paused }}>
      <img className={`w-full h-full object-${fit}`} src={video} />
      {video.state === 'error' ? (
        <div className="absolute left-0 top-0 w-full h-full flex flex-col items-center justify-center gap-[6px] px-[24px]">
          <span className={`text-[${Math.round(18 * k)}px] font-bold text-white`}>The video does not play</span>
          <span className={`text-[${Math.round(14 * k)}px] text-red-200 text-center`}>{video.error}</span>
        </div>
      ) : video.state === 'loading' ? (
        <span className={`absolute left-[16px] bottom-[12px] text-[${Math.round(13 * k)}px] text-white/60`}>Opening…</span>
      ) : paused ? (
        <div className={`absolute left-[16px] bottom-[12px] px-[10px] py-[4px] rounded-[6px] bg-black/60`}>
          <span className={`text-[${Math.round(14 * k)}px] text-white`}>
            {`Paused${video.duration ? ` at ${clock(video.time)} of ${clock(video.duration)}` : ''} · tap to play`}
          </span>
        </div>
      ) : null}
    </div>
  )
}
